  saddlebrown:[139,69,19], salmon:[250,128,114], sandybrown:[244,164,96],
  seagreen:[46,139,87], seashell:[255,245,238], sienna:[160,82,45],
  silver:[192,192,192], skyblue:[135,206,235], slateblue:[106,90,205],
